sys_script_fix.script:
// W3: one correlated logger for this script. Job sys_id is nil where this code has no job;
// the prefix degrades to [-] rather than vanishing. See the IllumioLogger script include.
var illumioLogger = new IllumioLogger(null, 'Add exisiting mapping to other table');

/**
 * This script will fetch the existing field mappings from PCE configuration
 * and add that field mapping to Illumio PCE Field Mappings table(x_illu2_illumio_illumio_pce_field_mapping)
 */

illumioLogger.info('Running "Add exisiting mapping to other table" fix script of Illumio');

// fetching PCE configuration record
var grPCEConfig = new GlideRecord('x_illu2_illumio_illumio_pce_conf');
grPCEConfig.setLimit(1);
grPCEConfig.query();

// Certification round 2, point 2. The same defect the certifier reported against "Migrate
// configurations" is here too, latent rather than visible. That script READS
// x_illu2_illumio_illumio_pce_field_mapping; this one WRITES it. The table was deleted from the
// application on 2025-08-21 (illumio-servicenow 67538ee, "chore: remove deprecated tables (#21)").
//
// It did not show up on the certifier's instance because servicenow_source_table and host_name
// still exist on pce_conf but are active="false" and empty on a fresh install, so the guard below
// takes the skip branch before reaching the dead table. On a real upgrading customer those legacy
// fields are populated and this fails -- and with no try/catch here, it fails uncaught, which is
// louder than what they actually reported.
//
// Guard, not removal, for the reason recorded in "Migrate configurations": the delete record
// belongs to 2.5.x's package rather than 2.6.0's, so an instance upgrading from 2.0-2.4 keeps the
// legacy table and still has a real migration to run.
var TABLE_LEGACY_PCE_FIELD_MAPPING = 'x_illu2_illumio_illumio_pce_field_mapping';

// check if record exists
if (grPCEConfig.next()) {

    if (!new GlideRecord(TABLE_LEGACY_PCE_FIELD_MAPPING).isValid()) {

        illumioLogger.info('Skipping field mapping record creation: the Illumio PCE Field Mappings table is not present on this instance.');

    } else if (!gs.nil(grPCEConfig.servicenow_source_table) && !gs.nil(grPCEConfig.host_name)) {

        // creating record in PCE field mapping
        var grPCEFieldMapping = new GlideRecord(TABLE_LEGACY_PCE_FIELD_MAPPING);
        grPCEFieldMapping.servicenow_source_table = grPCEConfig.servicenow_source_table;
        grPCEFieldMapping.host_name = grPCEConfig.host_name;
        grPCEFieldMapping.pce_configuration = grPCEConfig.sys_id;

        if (!gs.nil(grPCEConfig.application)) {
            grPCEFieldMapping.application = grPCEConfig.application;
        }
        if (!gs.nil(grPCEConfig.location)) {
            grPCEFieldMapping.location = grPCEConfig.location;
        }
        if (!gs.nil(grPCEConfig.role)) {
            grPCEFieldMapping.role = grPCEConfig.role;
        }
        if (!gs.nil(grPCEConfig.environment)) {
            grPCEFieldMapping.environment = grPCEConfig.environment;
        }
        if (!gs.nil(grPCEConfig.ip_address)) {
            grPCEFieldMapping.ip_address = grPCEConfig.ip_address;
        }

        if (!grPCEFieldMapping.insert()) {
            illumioLogger.error('Error while inserting field mapping record in PCE configuration');
        } else {
            illumioLogger.info('Successfully added field mapping in PCE field mapping table');
        }
    } else {
        illumioLogger.info('Source table or Host name is not selected in PCE configuration. Hence skipping the record creation for field mapping');
    }
} else {
    illumioLogger.info('No PCE configuration found for Illumio application. Hence skipping the record creation for field mapping');
}
